"use client";
import React, { useState } from "react";
import axios from "axios";
import { useRouter } from "next/navigation";
import Layout from "../../components/Layout";
import FormField from "../../components/FormField";
import { HiArrowNarrowLeft } from "react-icons/hi";
import { getYearOptions } from "../../utils/years";

const AddEtudiant = () => {
  const [inputs, setInputs] = useState({
    idEtudiant: "",
    nom: "",
    prenom: "",
    email: "",
    motDePasse: "",
    annee: "",
    classe: "",
    filiere: "",
  });

  const [error, setError] = useState("");
  const router = useRouter();

  const handleChange = (event) => {
    const { name, value } = event.target;
    setInputs(prev => ({ ...prev, [name]: value }));
  };

  const handleSubmit = async (event) => {
    event.preventDefault();
    setError("");
    try {
      await axios.post("http://localhost:5000/api/addetudiant", inputs);
      router.push("/users/readEtu");
    } catch (err) {
      setError("Erreur lors de l'ajout");
    }
  };

  return (
    <Layout>
      <div className="form-container w-full max-w-2xl mx-auto p-6">
        <button 
          onClick={() => router.push("/users/readEtu")} 
          className="back-button flex items-center text-[#1a4edb] hover:text-[#b17a56] transition-colors duration-300 mb-6"
        >
          <HiArrowNarrowLeft className="mr-2 text-2xl" />
          Retour
        </button>

        <div className="bg-white rounded-xl shadow-2xl p-8 border-t-4 border-[#1a4edb] transform transition-all hover:shadow-2xl">
          <h1 className="form-title text-3xl font-bold text-[#1a4edb] mb-2 text-center">
            Ajouter un Étudiant
          </h1>
          <div className="w-20 h-1 bg-[#b17a56] mx-auto mb-8 rounded-full"></div>

          {error && (
            <div className="error-message bg-red-100 border-l-4 border-red-500 text-red-700 p-4 mb-6 rounded">
              {error}
            </div>
          )}

          <form onSubmit={handleSubmit} className="space-y-6">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <FormField
                label="CIN"
                name="idEtudiant"
                value={inputs.idEtudiant}
                onChange={handleChange}
                placeholder="Entrez le CIN"
                required
                containerClass="transform transition-all hover:scale-[1.02]"
              />

              <FormField
                label="Nom"
                name="nom"
                value={inputs.nom}
                onChange={handleChange}
                placeholder="Entrez le nom"
                required
                containerClass="transform transition-all hover:scale-[1.02]"
              />

              <FormField
                label="Prénom"
                name="prenom"
                value={inputs.prenom}
                onChange={handleChange}
                placeholder="Entrez le prénom"
                required
                containerClass="transform transition-all hover:scale-[1.02]"
              />

              <FormField
                label="Email"
                name="email"
                type="email"
                value={inputs.email}
                onChange={handleChange}
                placeholder="Entrez l'email"
                required
                containerClass="transform transition-all hover:scale-[1.02]"
              />

              <FormField
                label="Mot de passe"
                name="motDePasse"
                type="password"
                value={inputs.motDePasse}
                onChange={handleChange}
                placeholder="Entrez le mot de passe"
                required
                containerClass="transform transition-all hover:scale-[1.02]"
              />

              <FormField
                label="Année"
                name="annee"
                type="select"
                value={inputs.annee}
                onChange={handleChange}
                options={getYearOptions()}
                required
                containerClass="transform transition-all hover:scale-[1.02]"
              />

              <FormField
                label="Classe"
                name="classe"
                value={inputs.classe}
                onChange={handleChange}
                placeholder="Entrez la classe"
                required
                containerClass="transform transition-all hover:scale-[1.02]"
              />

              <FormField
                label="Filière"
                name="filiere"
                value={inputs.filiere}
                onChange={handleChange}
                placeholder="Entrez la filière"
                required
                containerClass="transform transition-all hover:scale-[1.02]"
              />
            </div>

            <button 
              type="submit" 
              className="w-full py-3 px-4 bg-gradient-to-r from-[#1a4edb] to-[#1a4edbb2] text-white font-semibold rounded-lg shadow-md hover:from-[#1a4edbb2] hover:to-[#1a4edb] transform hover:scale-[1.02] transition-all duration-300 hover:shadow-xl"
            >
              Ajouter
            </button>
          </form>
        </div>
      </div>
    </Layout>
  );
};

export default AddEtudiant;